          (fun state -> ignore (pip_render state : string))
          [ Psp.Configure_identity (pip_config ~repos:[] ())
          ; Psp.Configure_identity
              (pip_config ~draft:(ps_draft ~id:(-1L) ()) ~repos:[] ())
          ; Psp.Configure_identity
              (pip_config
